var e=[{question:`¿Qué es EducaLabCR?`,answer:`EducaLabCR integra tecnología, formación e innovación aplicada. Su ecosistema reúne herramientas para la gestión docente, la creación de materiales y el trabajo de los equipos con inteligencia artificial.`},{question:`¿Qué puedo hacer con Sigma?`,answer:`Sigma acompaña la gestión académica y administrativa, el planeamiento didáctico y la preparación de recursos educativos. Podés explorar la demostración oficial para conocer sus herramientas.`},{question:`¿Cómo puedo conocer las opciones disponibles?`,answer:`Las opciones dependen de la herramienta y del contexto de uso. Consultá al equipo de EducaLabCR para conocer la disponibilidad, las condiciones y el acompañamiento adecuado para tu proyecto.`},{question:`¿Para qué sirve Luma?`,answer:`Luma permite transformar un tema, un texto o un apunte en una presentación. Ayuda a ordenar el contenido y a darle una forma visual clara, que después podés revisar y adaptar.`},{question:`¿Qué es Relay?`,answer:`Relay es una solución de agentes de inteligencia artificial y comunicación. Permite explorar formas de organizar la atención y acompañar los procesos de un equipo.`},{question:`¿EducaLabCR también ofrece formación?`,answer:`Sí. EducaLabCR ofrece cursos, talleres y capacitaciones en inteligencia artificial, investigación, tecnologías educativas y desarrollo profesional. Consultá la oferta oficial vigente.`},{question:`¿Puedo usar estas herramientas para preparar materiales?`,answer:`Podés explorar herramientas como Sigma y Luma para preparar recursos, documentos y presentaciones. Revisá siempre el contenido y adaptalo a los objetivos y características de tu grupo.`},{question:`¿Cómo elijo la solución para mi institución?`,answer:`Empezá por identificar la necesidad de tu comunidad educativa: organización, materiales, comunicación o formación. El equipo de EducaLabCR puede orientarte para evaluar las alternativas.`},{question:`¿Cómo me pongo en contacto?`,answer:`Podés usar los enlaces de contacto de este sitio para conversar con EducaLabCR a través de sus canales oficiales y contar qué necesitás para tu proyecto.`}];
